// Sweep 192.168.68.0/22 for TCP 502 (Modbus) and 8123, 80 on a few known hosts
const subnetBases = [68,69,70,71];
async function probe(host: string, port: number, ms = 700): Promise<boolean> {
  try {
    const s = await Promise.race([
      Bun.connect({ hostname: host, port, socket: { data(){}, open(sock){ sock.end(); }, error(){}, close(){} } }),
      new Promise<never>((_, rej) => setTimeout(() => rej(new Error("t")), ms)),
    ]);
    return true;
  } catch { return false; }
}
const hits: string[] = [];
const tasks: Promise<void>[] = [];
for (const b of subnetBases) for (let i = 1; i < 255; i++) {
  const h = `192.168.${b}.${i}`;
  tasks.push(probe(h, 502).then(ok => { if (ok) hits.push(`${h}:502`); }));
}
await Promise.all(tasks);
console.log("modbus502:", hits.join(" ") || "none");
EOF
